import React, { useState, useEffect } from 'react';
import { View, Text, TouchableOpacity } from 'react-native'
import { useContexState } from '../../hooks/context';

import Axios from 'axios';
import Firebase from '../../config'

import { GetCards } from '../../components/GetCards'
import { Cards } from '../../components/Cards'

import { useLoadPage } from '../../hooks/loadPage'

import { styles } from './styles'

interface DataType {
    data: {
        lineCards: number;
        id: number;
    }
}


export function ListItem(props: any) {

    const {
        dataServer
    } = useContexState()


    function buttonAdd() {
        Axios.post("http://18.191.178.251:3000/register", {
            name: 'teste00',
            price: 190,
        }).then((response) => console.warn(response));
    }


    interface qwe {
        id?: number;
        price?: number;
        name?: string;
    }


    return (
        <View style={styles.listItem}>
            <Text style={{ fontSize: 20, position: 'absolute', backgroundColor: 'rgba(0,0,0,0.8)', padding: 5, color: '#fff' }}>{props.zxc?.['Fabio Moraes'][0]['price']}</Text>
            <TouchableOpacity onPress={buttonAdd}>
                <Text style={[styles.listText, { backgroundColor: '#fff', color: '#121212' }]}>
                    {("0000" + props.data.lineCards).slice(-4)}
                </Text>
            </TouchableOpacity>

            <Cards props={props} position={1} />

        </View>
    );
};


